import{_ as o,o as a,c as s,a0 as n,j as e}from"./chunks/framework.BxpcW2R3.js";const m=JSON.parse('{"title":"Molecule Laws","description":"","frontmatter":{},"headers":[],"relativePath":"Molecule-Laws.md","filePath":"Molecule-Laws.md"}'),i={name:"Molecule-Laws.md"};function r(l,t,c,d,p,u){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="molecule-laws" tabindex="-1">Molecule Laws <a class="header-anchor" href="#molecule-laws" aria-label="Permalink to &quot;Molecule Laws&quot;">​</a></h1><p>This document defines the architectural meaning of a molecule in this.GUI.</p><h2 id="definition" tabindex="-1">Definition <a class="header-anchor" href="#definition" aria-label="Permalink to &quot;Definition&quot;">​</a></h2><p>A molecule is a declarative law registered in <code>GuiRegistry</code>: it receives a small semantic spec, applies an explicit policy, and deterministically produces or renders a tree of GuiNodes.</p><p>A molecule learns when the system gains better registered laws, policies, constraints, and tests. It must not improvise silently at runtime.</p><h2 id="kinds" tabindex="-1">Kinds <a class="header-anchor" href="#kinds" aria-label="Permalink to &quot;Kinds&quot;">​</a></h2><p><code>resolver</code> : A pure law. It receives data and policy, then returns GuiNodes. It has no I/O, subscriptions, timers, or browser state.</p><p><code>shell</code> : A stateful boundary around one or more resolvers. It may fetch, subscribe, handle loading/error states, or read runtime context. The shape law inside the shell should still be pure and testable.</p><p><code>component</code> : A React component used directly when the behavior is primarily interactive or physical. Components can still expose semantic props, but they are not the preferred place for shape-learning rules.</p><h2 id="registry" tabindex="-1">Registry <a class="header-anchor" href="#registry" aria-label="Permalink to &quot;Registry&quot;">​</a></h2><p>For now all laws live in <code>GuiRegistry</code>. Molecules should use:</p><ul><li><code>kind: &quot;molecule&quot;</code></li><li><code>group: &quot;Molecules/&lt;Domain&gt;&quot;</code></li><li><code>moleculeKind: &quot;resolver&quot; | &quot;shell&quot; | &quot;component&quot;</code></li></ul><p>This keeps atoms, layouts, and molecules discoverable through one registry without hiding the kind of law being registered.</p><h2 id="markdowndocument" tabindex="-1">MarkdownDocument <a class="header-anchor" href="#markdowndocument" aria-label="Permalink to &quot;MarkdownDocument&quot;">​</a></h2><p><code>MarkdownDocument</code> is the first document molecule following this split:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MarkdownDocument shell</span></span>
<span class="line"><span>  fetch/loading/error</span></span>
<span class="line"><span>  -&gt; markdownToGuiNodes(source, policy)</span></span>
<span class="line"><span>  -&gt; GuiNode tree</span></span>
<span class="line"><span>  -&gt; GUI renderer</span></span></code></pre></div><p>The public contract is GUI-owned. It must not expose parser or renderer implementation details such as <code>@uiw</code>, <code>remark</code>, or <code>unified</code>.</p>`,17),e("footer",{style:{"margin-top":"56px",padding:"24px 0","text-align":"center","border-top":"1px solid rgba(128,128,128,0.15)"}},[e("a",{href:"https://neurons.me",target:"_blank",rel:"noopener",style:{display:"inline-flex","align-items":"center",gap:"8px","text-decoration":"none",opacity:"0.45",transition:"opacity 120ms"},onmouseover:"this.style.opacity=0.9",onmouseout:"this.style.opacity=0.45"},[e("img",{src:"https://res.cloudinary.com/dkwnxf6gm/image/upload/v1760629056/neurons-grey_hxjcom.png",alt:"neurons.me",style:{width:"24px",height:"24px","object-fit":"contain"}}),e("span",{style:{"font-size":"0.8rem","font-weight":"600",color:"inherit","letter-spacing":"0.04em"}},"neurons.me")])],-1)])])}const g=o(i,[["render",r]]);export{m as __pageData,g as default};
